<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$s=$conn->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=? AND status="active"');$s->bind_param('s',$email);$s->execute();$r=$s->get_result();$u=$r->fetch_assoc();if($u&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['name']=$u['name'];$_SESSION['email']=$u['email'];$_SESSION['role']=$u['role'];$_SESSION['last_activity']=time();audit($conn,'auth.login','Successful login');header('Location: '.BASE_URL.'/dashboard.php');exit;}else{$error='Email or password is incorrect.';audit($conn,'auth.login_failed','Failed login attempt');}$s->close();}$pageTitle='Login | StudentHub';require __DIR__.'/../includes/header.php'; ?><span class="eyebrow">Welcome back</span><h1>Sign in to StudentHub</h1><?php if(isset($_GET['expired'])): ?><p class="notice">Your session expired. Please sign in again.</p><?php endif;if($error): ?><p class="error notice"><?= e($error) ?></p><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="username"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" required autocomplete="current-password"></div><button class="button">Sign in</button><p>New to StudentHub? <a href="register.php">Create account</a></p><p class="muted">For admin testing, register your own account and promote it to role=admin using the SQL instruction in README.md.</p></form><?php require __DIR__.'/../includes/footer.php'; ?>
